            imagePosition: 'top',
            content:       null,
            variant:       null,
            loading:       null,
            horizontal:    false,
            hoverable:     false,
            actions:       [],
            renderImage:   null,
            renderHeader:  null,
            renderContent: null,
            renderFooter:  null,
            renderActions: null,
            layout:        null,
