    /**
     *  @class
     *  */
    function HasDraggable() {}


    /**
     * @param {number} x
     * @param {number} y
     */
    HasDraggable.prototype.move = function(x, y) {
        if(!this.$movableElement) {
            return;
        }

        this.$movableElement.style.left   = x + 'px';
        this.$movableElement.style.top    = y + 'px';
        this.$movableElement.style.margin = '0';
    };

    /**
     * @param {HTMLElement} parent
     * @param {HTMLElement|null} [grip=null]
     * @returns {() => void}
     */
    HasDraggable.prototype.makeDraggable = function(parent, grip = null) {
        if(!this.emit) {
            throw new Error('HasDraggable requires HasEventEmitter - add it via BaseComponent.use(Component, HasEventEmitter, HasDraggable).');
        }
        this.$movableElement = parent;

        const gripElement = grip || parent;
        gripElement.classList.add('is-draggable');

        let isDragging = false;
        let startX     = 0;
        let startY     = 0;
        let initialX   = 0;
        let initialY   = 0;

        const onMouseDown = (e) => {
            isDragging = true;
            startX     = e.clientX;
            startY     = e.clientY;
            initialX   = parent.offsetLeft;
            initialY   = parent.offsetTop;
            this.emit('onDragStart', [e, initialX, initialY]);

            gripElement.classList.add('is-dragging');
        };

        const onMouseMove = (e) => {
            if(!isDragging) {
                return;
            }

            const x = initialX + (e.clientX - startX);
            const y = initialY + (e.clientY - startY);

            this.move(x, y);
            this.emit('onDrag', [e, x, y]);
        };

        const onMouseUp = () => {
            isDragging = false;
            this.emit('onDragEnd');
            gripElement.classList.remove('is-dragging');
        };

        gripElement.addEventListener('mousedown', onMouseDown);
        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);

        return () => {
            gripElement.removeEventListener('mousedown', onMouseDown);
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
        };
    };

    /**
     *
     * @constructor
     */
    function HasResizable() {}

    /**
     * @param {HTMLElement} parent
     * @param {{ directions?: string[], size?: { minWidth?: number, maxWidth?: number, minHeight?: number, maxHeight?: number } }} [options={}]
     * @returns {() => void}
     */
    HasResizable.prototype.makeResizable = function(parent, options = {}) {
        if(!this.emit) {
            throw new Error('HasResizable requires HasEventEmitter — add it via BaseComponent.use(Component, HasEventEmitter).');
        }

        const directions = options.directions || ['right', 'bottom', 'bottom-right'];
        const sizeConstraint = options.size || { minWidth: 200, minHeight: 200 };
        sizeConstraint.minWidth = sizeConstraint.minWidth || 200;
        sizeConstraint.minHeight = sizeConstraint.minHeight || 200;

        parent.classList.add('is-resizable');

        const handles = [];

        directions.forEach((direction) => {
            const handle = document.createElement('div');
            handle.className = 'resize-handle is-' + direction;
            parent.appendChild(handle);
            handles.push(handle);

            setupResizeHandle(handle, parent, direction, sizeConstraint, this);
        });

        return () => {
            handles.forEach(h => h.remove());
        };
    };

    const setupResizeHandle = (handle, parent, direction, sizeConstraint, instance) => {
        let isResizing = false;
        let startX     = 0;
        let startY     = 0;
        let startW     = 0;
        let startH     = 0;
        let startLeft  = 0;
        let startTop   = 0;

        const onMouseDown = (e) => {
            e.preventDefault();
            e.stopPropagation();

            isResizing = true;
            startX     = e.clientX;
            startY     = e.clientY;
            startW     = parent.offsetWidth;
            startH     = parent.offsetHeight;
            startLeft  = parent.offsetLeft;
            startTop   = parent.offsetTop;

            document.body.classList.add('is-resizing');
            instance.emit?.('onResizeStart', [e, startW, startH]);
        };

        const onMouseMove = (e) => {
            if(!isResizing) {
                return;
            }

            const dx = e.clientX - startX;
            const dy = e.clientY - startY;

            if(direction === 'right' || direction === 'top-right' || direction === 'bottom-right') {
                const newWidth = Math.max(sizeConstraint.minWidth, startW + dx);
                if(newWidth > sizeConstraint.minWidth && (!sizeConstraint.maxWidth || newWidth <= sizeConstraint.maxWidth)) {
                    parent.style.width = newWidth + 'px';
                }
            }

            if(direction === 'left' || direction === 'top-left' || direction === 'bottom-left') {
                const newWidth = Math.max(sizeConstraint.minWidth, startW - dx);
                if(newWidth > sizeConstraint.minWidth && (!sizeConstraint.maxWidth || newWidth <= sizeConstraint.maxWidth)) {
                    parent.style.width = newWidth + 'px';
                    parent.style.left  = (startLeft + dx) + 'px';
                }
            }

            if(direction === 'bottom' || direction === 'bottom-right' || direction === 'bottom-left') {
                const newHeight = Math.max(sizeConstraint.minHeight, startH + dy);
                if(newHeight > sizeConstraint.minHeight && (!sizeConstraint.maxHeight || newHeight <= sizeConstraint.maxHeight)) {
                    parent.style.height = newHeight + 'px';
                }
            }

            if(direction === 'top' || direction === 'top-right' || direction === 'top-left') {
                const newHeight = Math.max(sizeConstraint.minHeight, startH - dy);
                if(newHeight > sizeConstraint.minHeight && (!sizeConstraint.maxHeight || newHeight <= sizeConstraint.maxHeight)) {
                    parent.style.height = newHeight + 'px';
                    parent.style.top    = (startTop + dy) + 'px';
                }
            }

            instance.emit?.('onResize', [e, parent.offsetWidth, parent.offsetHeight]);
        };

        const onMouseUp = () => {
            if(!isResizing) {
                return;
            }

            isResizing = false;
            document.body.classList.remove('is-resizing');
            instance.emit?.('onResizeEnd', [parent.offsetWidth, parent.offsetHeight]);
        };

        handle.addEventListener('mousedown', onMouseDown);
        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
    };

    /**
     * Dialog overlay with header, content, and footer slots. Supports draggable, resizable, scroll lock, focus trap, and close-on-backdrop/escape.
     *
     *
     * @example
     * const modal = new Modal(Div('Modal body content'))
     *     .title(Span('Confirm deletion'))
     *     .footer(HStack(cancelBtn, confirmBtn))
     *     .size('medium')
     *     .centered()
     *     .closeOnEscape(true)
     *     .closable(true)
     *     .focusTrap(true)
     *     .onOpen(() => console.log('opened'))
     *     .onClose(() => console.log('closed'));
     *
     * // Attach to trigger
     * const triggerEl = modal.trigger(Button(Span('Open')));
     *
     * Modal.use((description, instance) => {
     *     return Div(
     *         { class: 'modal' },
     *         description.title,
     *         description.content,
     *         description.footer
     *     );
     * });
     *
     * @constructor
     * @param {NdChild} content
     * @param {GlobalAttributes} [props={}]
     */
    function Modal(content, props = {}) {
        if(!(this instanceof Modal)) {
            return new Modal(content, props);
        }

        BaseComponent.call(this, props);

        this.$description = {
            centered: true,
            scrollable: false,
            title: null,
            content,
            footer: null,
            size: null,
            closeOnBackdrop: true,
            closeOnEscape: true,
            closable: true,
            layout: null,
            fullscreen: false,
            draggable: false,
            dragByHeader: true,
            resizable: false,
            resizableOptions: { size: {} },
            focusTrap: true,
            lockScroll: true,
            isOpen: Observable(false),
            variant: null,
            props,
        };
    }

    BaseComponent.extends(Modal);
    BaseComponent.use(Modal, HasEventEmitter, HasDraggable, HasResizable);

    // Theming
    Modal.defaultTemplate = null;

    /**
     * Registers the render template for Modal.
     * @param {(description: {
     *     centered: boolean,
     *     scrollable: boolean,
     *     title: NdChild|null,
     *     content: NdChild,
     *     footer: NdChild|null,
     *     size: 'small'|'medium'|'large'|'extra-large'|'fullscreen'|null,
     *     closeOnBackdrop: boolean,
     *     closeOnEscape: boolean,
     *     closable: boolean,
     *     layout: ((desc: *, instance: Modal) => NdChild)|null,
     *     fullscreen: boolean,
     *     draggable: boolean,
     *     dragByHeader: boolean,
     *     resizable: boolean,
     *     focusTrap: boolean,
     *     lockScroll: boolean,
     *     isOpen: Observable<boolean>,
     *     variant: string|null,
     *     props: GlobalAttributes,
     * }, instance: Modal) => NdChild} template
     */
    Modal.use = function(template) {
        Modal.defaultTemplate = template;

        if(!NDElement.prototype.modal) {
            NDElement.prototype.modal = function(content, props) {
                const modal = (content instanceof Modal) ? content : Modal(content, props);
                modal.toNdElement();
                this.onClick(() => modal.open());
                return this;
            };
        }
        if(!BaseComponent.prototype.modal) {
            BaseComponent.prototype.modal = function(content, props) {
                this.postBuild(() => {
                    const modal = (content instanceof Modal) ? content : Modal(content, props);
                    modal.toNdElement();
                    this.nd.onClick(() => modal.open());
                });
                return this;
            };
        }
    };

    /**
     * @param {HTMLElement|NDElement} trigger
     * @returns {HTMLElement|NDElement}
     */
    Modal.prototype.trigger = function(trigger) {
        this.toNdElement();
        trigger.nd.onClick(() => this.open());
        return trigger;
    };

    /**
     * @param {string} name
     * @param {(m: Modal) => Modal} callback
     */
